import numpy as np
from tc_research import benter as B


def simulate(n, alpha, beta, model_noise, rng):
    """Truth is generated by the Benter blend of a latent 'true' model and the market."""
    groups = []
    for _ in range(n):
        k = 6
        true = rng.dirichlet(np.ones(k) * 2.0)
        market = np.clip(true * np.exp(rng.normal(0, 0.35, k)), 1e-6, None); market /= market.sum()
        model = np.clip(true * np.exp(rng.normal(0, model_noise, k)), 1e-6, None); model /= model.sum()
        p = B.combine(model, market, alpha, beta)
        groups.append(B.Group(model, market, int(rng.choice(k, p=p))))
    return groups


def test_fit_recovers_parameters():
    rng = np.random.default_rng(0)
    groups = simulate(6000, alpha=0.6, beta=0.7, model_noise=0.2, rng=rng)
    a, b = B.fit(groups)
    assert abs(a - 0.6) < 0.12 and abs(b - 0.7) < 0.12, (a, b)


def test_informative_model_has_positive_oos_delta_r2_noise_model_does_not():
    rng = np.random.default_rng(1)
    good = simulate(5000, 0.7, 0.6, model_noise=0.15, rng=rng)
    r = B.oos_delta_r2(good)
    assert r["delta_R2"] > 0.005, r
    # a model that is pure noise relative to truth: truth follows the market only (alpha=0)
    noise = []
    for _ in range(5000):
        true = rng.dirichlet(np.ones(6) * 2.0)
        market = true.copy()
        model = rng.dirichlet(np.ones(6) * 2.0)           # unrelated to outcomes
        noise.append(B.Group(model, market, int(rng.choice(6, p=true))))
    r2 = B.oos_delta_r2(noise)
    assert r2["delta_R2"] < 0.002, r2
    assert abs(r2["alpha"]) < 0.15, r2


def test_binary_matches_rust_formula():
    # Rust: benter_combine_binary(f, pi, a, b); identity at alpha=0, beta=1
    p = B.combine(np.array([0.9, 0.1]), np.array([0.3, 0.7]), 0.0, 1.0)
    assert abs(p[0] - 0.3) < 1e-12
